/** A provider-neutral plan, as `contracts/v1/provider-driver-process.schema.json` defines it. Every member is optional; each is a 64-digit lowercase SHA-256, except `priorDeploymentId`, which is a canonical UUIDv7. */
export type ProviderNeutralPlan = {
  /** SHA-256 of the binding snapshot. */
  bindingSnapshotDigest?: string;
  /** The deployment this one supersedes. */
  priorDeploymentId?: string /* uuid */;
  /** SHA-256 of the route plan. */
  routePlanDigest?: string;
  /** SHA-256 of the traffic policy. */
  trafficPolicyDigest?: string;
  /** SHA-256 of the trigger plan. */
  triggerPlanDigest?: string;
};

/**
 * The stored identity of a driver-deployed provider payload: exactly what
 * `POST …/provider-deployments` names in its `artifact`.
 */
export type ProviderPayloadUploadResponse = {
  /** The canonical parent this payload was derived from. */
  artifactId: string /* uuid */;
  /** False when this exact derivation was already recorded. */
  created: boolean;
  /** Identity of the derivation record. */
  manifestSha256: string;
  /**
   * File-set digest of the payload tree; a provider deployment's
   * `artifact.providerPayloadSha256`.
   */
  payloadRootSha256: string;
  /** `cloudflare`. */
  provider: string;
  standardVersion: string;
};

export type ProviderTarget = {
  backendId: string;
  createdAt: string /* date-time */;
  /**
   * Set once by a soft delete and never cleared. A deleted target keeps
   * the terminal `disabled` status the table already allows.
   */
  deletedAt?: string /* date-time */ | null;
  driverDistributionDigest: string;
  driverId: string;
  driverManifestDigest: string;
  driverReleaseDigest: string;
  driverVersion: string;
  installationId: string /* uuid */;
  /**
   * The owning installation's status. A target only accepts new work when
   * both it and its installation are `active`; this lets a client see why
   * an `active` target is not usable.
   */
  installationStatus: string;
  name: string;
  revision: number /* int64 */;
  standardContractDigest: string;
  standardContractId: string;
  standardVersion: string;
  status: string;
  targetConfigDigest: string;
  targetId: string /* uuid */;
  updatedAt: string /* date-time */;
};

export type ProviderTargetGrant = {
  applicationId: string /* uuid */;
  backendId: string;
  createdAt: string /* date-time */;
  environmentId: string /* uuid */;
  grantId: string /* uuid */;
  grantedByActorId: string /* uuid */;
  note?: string | null;
  organizationId: string /* uuid */;
  providerTargetId: string /* uuid */;
  revision: number /* int64 */;
  revokedAt?: string /* date-time */ | null;
  revokedByActorId?: string /* uuid */ | null;
  status: string;
  targetName: string;
  targetRevision: number /* int64 */;
  targetStandardVersion: string;
  targetStatus: string;
  updatedAt: string /* date-time */;
};

export type ProviderTargetGrantAuditEvent = {
  actorId: string /* uuid */;
  applicationId: string /* uuid */;
  environmentId: string /* uuid */;
  eventId: string /* uuid */;
  eventType: string;
  grantId: string /* uuid */;
  grantRevision: number /* int64 */;
  occurredAt: string /* date-time */;
  providerTargetId: string /* uuid */;
  /**
   * Present on `revoked` events written since revocation reasons exist;
   * `None` on `granted` events and on revocations that predate the column.
   */
  reason?: string | null;
};

/** Which step list a workflow journal runs. */
export type ProviderWorkflowKind = "deploy" | "rollback";

export type ProvisionCredentialRequest = {
  /**
   * Provider-specific account identifier (e.g., Cloudflare account ID).
   * Passed as `account_id` to the credential binding spec.
   */
  accountId?: string | null;
  backendId: string;
  credential: string;
  name: string;
};

export type PutSecretRequest = {
  /**
   * Plaintext value. It is encrypted before it touches the database and
   * is never written to a log.
   */
  value: string;
};

export type RegisterInstallationRequest = {
  accountReference: string;
  backendId: string;
  credentialBindingId: string /* uuid */;
  region?: string | null;
};

export type RegisterTargetRequest = {
  driverManifest: ProviderDriverManifest;
  name: string;
  standardVersion: string;
  targetConfigDigest: string;
};

export type ReleaseRetiredAppResponse = {
  /**
   * What the caller has just accepted, spelled out: the next application
   * created under this name is the same storage tenant as the deleted one.
   */
  accepted: string;
  app_id: string;
  released: RetiredAppName;
};

/**
 * What came of taking an application off the fleet.
 *
 * Deleting an application is the one operation whose failure is silent
 * without this: the rows are gone from the catalog, so nothing will ever
 * mention the app again, while a node that was not reached keeps serving
 * it - with its code, its secrets in memory and its queue consumers still
 * polling - until that process restarts.
 */
export type RemovalReport = {
  app_id: string;
  /**
   * Environment names the catalog had for this app when it was deleted.
   * Informational: the nodes are told to drop every environment of it.
   */
  environments: string[];
  /** Nodes that did not. **These still serve the deleted application.** */
  failed: NodeFailure[];
  /** Set when nothing was sent at all, with the reason. */
  skipped?: string | null;
  /** Nodes that dropped it and no longer serve it. */
  unloaded: string[];
};

/** The node's own resource reading. */
export type ResourceUsageView = {
  cpu_percent: number /* double */;
  memory_bytes: number /* int64 */;
};

/** An algorithm-tagged digest. */
export type RestoreDigest = {
  /** `sha256`. */
  algorithm: string;
  /** 64 lowercase hexadecimal digits. */
  value: string;
};

/**
 * A name that belonged to an application which has been deleted, and which
 * is therefore not free.
 *
 * Deleting an application removes it from this catalog and leaves everything
 * it stored where it was: deis-store and deis-queue key a tenant by
 * `(application, environment)` and neither of them has an operation that
 * drops one. So the name is retained rather than the data, and nothing can
 * be deployed onto it until somebody says out loud that the next application
 * of that name may have what the last one left - see
 * `CatalogStore::release_retired_name`.
 */
export type RetiredAppName = {
  app_id: string;
  /**
   * The environments it had when it was deleted, in name order.
   *
   * One environment is one tenant, so this is the list of places its data
   * still is. It can be empty - an application deleted before it had an
   * environment - and the name is retained all the same: a storage token
   * is minted per environment on request, and an environment that was
   * created and used is not distinguishable here from one that was never
   * touched.
   *
   * A name that has been used, deleted, released and used again carries
   * the environments of every application that had it, because every one
   * of those tenants may still hold data.
   */
  environments: string[];
  /**
   * When an operator freed the name again, if they have.
   *
   * `None` is a name that is still held, which is the only state that
   * stops an application being created under it. The row survives the
   * release rather than being deleted, because what it records - which
   * tenants hold data under this name - stays true afterwards, and the
   * next deletion of the same name has to add to that list rather than
   * start a new one.
   */
  released_at?: number /* int64 */ | null;
  /** When the application was deleted, Unix epoch seconds. */
  retired_at: number /* int64 */;
};

/**
 * What an account is allowed to hold.
 *
 * A role is a ceiling, not a grant: it says which verbs this account's
 * tokens may carry, and it is re-checked on every request rather than only
 * when a token is minted. That is what makes a demotion mean something -
 * moving an account from `owner` to `viewer` reduces every token it already
 * holds to reading, at the next request, without anybody having to hunt
 * those tokens down.
 */
export type Role = "owner" | "maintainer" | "deployer" | "viewer";

/** Which recorded version to restore. */
export type RollbackRequest = {
  /** The `version_timestamp` of a history entry for this key. */
  version_timestamp: string /* date-time */;
};

export type RotateCredentialRequest = {
  credential: string;
};

/**
 * A host plus path prefix bound to one environment. `host: None` matches
 * any domain.
 */
export type Route = {
  app_id: string;
  env_id: string;
  host?: string | null;
  id: string;
  path_prefix: string;
  priority: number /* int64 */;
};

/** A route was removed. */
export type RouteDeleted = {
  /** The id of the route that was removed. */
  deleted: string;
};

export type RouteRequest = {
  /**
   * Omit or null to match any domain - which is the *widest* claim on
   * this platform, not the mildest, and needs the widest grant.
   */
  host?: string | null;
  path_prefix: string;
  /**
   * Higher wins when several routes match. Defaults to 0, and is bounded
   * (`catalog::model::MAX_ROUTE_PRIORITY`) because it is a caller-supplied
   * integer that becomes an ordering key at the edge.
   */
  priority?: number /* int64 */;
};

export type RouteResponse = {
  route: Route;
};

/**
 * What a write to a secret answers: the metadata of the secret itself -
 * never its value - plus where the reloaded deployment landed.
 */
export type SecretChangeResponse = {
  /**
   * Nodes that picked the new environment up. A secret change creates
   * no version, so this is the only evidence it reached anything.
   */
  delivery: DeliveryReport;
  plan?: DeploymentPlan;
  secret: SecretMeta;
};

/** What deleting a secret answers. */
export type SecretDeletedResponse = {
  deleted: string;
  delivery: DeliveryReport;
  plan?: DeploymentPlan;
};

/**
 * What a caller is allowed to learn about a secret: that it exists and
 * when it last changed. The value never leaves the control plane except
 * as part of a deployment payload to a node.
 */
export type SecretMeta = {
  name: string;
  /** Opaque immutable revision identity. A later write creates another one. */
  revision: string;
  updated_at: number /* int64 */;
};

/** One open control channel. */
export type SessionView = {
  connected_at: string;
  host: string;
  id: string;
  instance_id: string;
  last_heartbeat: string;
  node_role: string;
  ports: Array<number /* int32 */>;
  state: string;
};

/** Every open control channel. */
export type SessionsResponse = {
  sessions: SessionView[];
  total: number;
};

/**
 * What a caller needs in order to act as one tenant of deis-store.
 *
 * Every field is always present: an answer carrying an empty token would be
 * one the caller cannot use, so that case is a refusal rather than a field
 * left blank.
 */
export type StorageTokenResponse = {
  /**
   * The Ed25519 capability token for deis-queue, for the same header on
   * calls to deis-queue. A separate token because deis-queue accepts only
   * its own audience.
   */
  queue_token: string;
  /** Where deis-store listens, as configured on this control plane. */
  store_endpoint: string;
  /**
   * The `<app>.<environment>` pair the token authorises. Included so
   * a caller never has to rebuild it, and so the tenant this control
   * plane signed is visible to anyone debugging a refused call.
   */
  tenant: string;
  /**
   * The Ed25519 capability token for deis-store (kv, sql and blob), for
   * the `Authorization: Bearer` header.
   */
  token: string;
};

/** Process-wide counters. */
export type SystemCounts = {
  total_commands: number;
  total_events: number;
  total_heartbeats: number;
  uptime_seconds: number /* int64 */;
};

/** Where a credential came from. */
export type TokenOrigin = "minted" | "bootstrap";

/**
 * The unload was not sent, and why. Not the `ErrorBody` envelope: this
 * answer predates it and is kept byte for byte on every prefix.
 */
export type UnloadRefused = {
  /** On 409: the environments the catalog still deploys to this node. */
  assigned_environments?: string[];
  /**
   * On 409: how often the node reconciles its assignment list, in
   * seconds - the time within which the application would be back.
   */
  assignment_refresh_seconds?: number /* int64 */;
  /** Why nothing was sent, and what to do instead. */
  error: string;
  success: boolean;
};

export type UpdateAccountRequest = {
  /**
   * Absent means "leave it". `true` refuses every token of this account
   * without revoking any of them.
   */
  disabled?: boolean | null;
  /** Absent means "leave it". */
  role?: string | null;
};

/** The keys to set on a node. Keys not named are left as they are. */
export type UpdateConfigRequest = {
  configs: { [key: string]: Value };
};

export type UploadResponse = {
  bundle_url: string;
  /**
   * False when a byte-identical bundle was already recorded, in which
   * case the existing version is returned unchanged.
   */
  created: boolean;
  version: VersionView;
};

export type Value = unknown;

/**
 * Version as seen from outside. `bundle_path` is deliberately absent: it
 * is a control-plane local path and no client has any use for it.
 */
export type VersionView = {
  app_id: string;
  bundle_sha: string;
  /**
   * Exact provider-neutral parent and provider derivation. Both are absent
   * only for legacy raw-bundle uploads.
   */
  canonical_artifact_id?: string /* uuid */;
  canonical_id: string /* uuid */;
  compatibility?: null | CompatibilityProfile;
  created_at: number /* int64 */;
  id: string;
  /** The manifest as structured JSON, parsed from the stored text. */
  manifest: unknown;
  number: number /* int64 */;
  provider_derivation_sha256?: string;
};

